/**
 * Explicit initial installation. Existing tables cause a failure and rollback.
 * Evolving a populated database requires a reviewed application migration.
 * Use the same prefix when loading StorageManifest::withPrefix().
 */
return static function (\PDO $database, string $prefix = ''): void {
    if ($database->getAttribute(\PDO::ATTR_DRIVER_NAME) !== 'sqlite') {
        throw new \InvalidArgumentException('This installer requires PDO SQLite.');
    }
    if ($prefix !== '' && !preg_match('/^[A-Za-z_][A-Za-z0-9_]*$/D', $prefix)) {
        throw new \InvalidArgumentException('Invalid SQLite table prefix.');
    }
    if ($database->inTransaction()) {
        throw new \LogicException('Run the initial installer outside an existing transaction.');
    }
    $database->exec('PRAGMA foreign_keys = ON');
    $table = static fn (string $name): string => '"' . $prefix . $name . '"';
    $statements = [
        'CREATE TABLE ' . $table('phe_author') . ' (
    ' . '"id" INTEGER PRIMARY KEY AUTOINCREMENT' . ',
    ' . '"name" TEXT NOT NULL CHECK (length("name") <= 120)' . '
)',
        'CREATE TABLE ' . $table('phe_comment') . ' (
    ' . '"id" INTEGER PRIMARY KEY AUTOINCREMENT' . ',
    ' . '"body" TEXT NOT NULL' . ',
    ' . '"author_id" INTEGER' . ' REFERENCES ' . $table('phe_author') . '("id") ON DELETE RESTRICT' . ',
    ' . '"post_id" INTEGER' . ' REFERENCES ' . $table('phe_post') . '("id") ON DELETE RESTRICT' . '
)',
        'CREATE INDEX ' . $table('phe_comment_author_id_idx') . ' ON ' . $table('phe_comment') . ' ("author_id")',
        'CREATE INDEX ' . $table('phe_comment_post_id_idx') . ' ON ' . $table('phe_comment') . ' ("post_id")',
        'CREATE TABLE ' . $table('phe_post') . ' (
    ' . '"id" INTEGER PRIMARY KEY AUTOINCREMENT' . ',
    ' . '"created_at" TEXT NOT NULL' . ',
    ' . '"updated_at" TEXT NOT NULL' . ',
    ' . '"post_id" INTEGER' . ',
    ' . '"slug" TEXT NOT NULL CHECK (length("slug") <= 120)' . ',
    ' . '"title" TEXT NOT NULL CHECK (length("title") <= 200)' . ',
    ' . '"price" INTEGER' . ',
    ' . '"status" TEXT NOT NULL CHECK ("status" IN (\'draft\', \'scheduled\', \'published\'))' . ',
    ' . '"visibility" TEXT NOT NULL CHECK ("visibility" IN (\'public\', \'private\'))' . ',
    ' . '"published_at" TEXT' . ',
    ' . '"extra_int" INTEGER' . ',
    ' . '"extra_float" REAL' . ',
    ' . '"extra_bool" INTEGER CHECK ("extra_bool" IN (0, 1))' . ',
    ' . '"extra_json" TEXT' . ',
    ' . '"extra_id" INTEGER' . ',
    ' . '"featured_author_id" INTEGER' . ' REFERENCES ' . $table('phe_author') . '("id") ON DELETE RESTRICT' . '
)',
        'CREATE UNIQUE INDEX ' . $table('phe_post_post_id_uniq') . ' ON ' . $table('phe_post') . ' ("post_id")',
        'CREATE INDEX ' . $table('phe_post_title_idx') . ' ON ' . $table('phe_post') . ' ("title")',
        'CREATE UNIQUE INDEX ' . $table('phe_post_featured_author_id_uniq') . ' ON ' . $table('phe_post') . ' ("featured_author_id")',
        'CREATE TABLE ' . $table('phe_post_related') . ' (
    ' . '"post_id" INTEGER NOT NULL' . ' REFERENCES ' . $table('phe_post') . '("id") ON DELETE RESTRICT' . ',
    ' . '"related_id" INTEGER NOT NULL' . ' REFERENCES ' . $table('phe_post') . '("id") ON DELETE RESTRICT' . '
)',
        'CREATE UNIQUE INDEX ' . $table('phe_post_related_pair_uniq') . ' ON ' . $table('phe_post_related') . ' ("post_id", "related_id")',
        'CREATE INDEX ' . $table('phe_post_related_related_id_idx') . ' ON ' . $table('phe_post_related') . ' ("related_id")',
        'CREATE TABLE ' . $table('phe_post_tags') . ' (
    ' . '"post_id" INTEGER NOT NULL' . ' REFERENCES ' . $table('phe_post') . '("id") ON DELETE RESTRICT' . ',
    ' . '"tag_id" INTEGER NOT NULL' . ' REFERENCES ' . $table('phe_tag') . '("id") ON DELETE RESTRICT' . '
)',
        'CREATE UNIQUE INDEX ' . $table('phe_post_tags_pair_uniq') . ' ON ' . $table('phe_post_tags') . ' ("post_id", "tag_id")',
        'CREATE INDEX ' . $table('phe_post_tags_tag_id_idx') . ' ON ' . $table('phe_post_tags') . ' ("tag_id")',
        'CREATE TABLE ' . $table('phe_tag') . ' (
    ' . '"id" INTEGER PRIMARY KEY AUTOINCREMENT' . ',
    ' . '"label" TEXT NOT NULL' . '
)',
        'CREATE UNIQUE INDEX ' . $table('phe_tag_label_uniq') . ' ON ' . $table('phe_tag') . ' ("label")',
    ];
    $database->beginTransaction();
    try {
        foreach ($statements as $sql) {
            if ($database->exec($sql) === false) {
                $detail = $database->errorInfo()[2] ?? null;
                throw new \RuntimeException('SQLite schema installation failed: ' . (is_string($detail) ? $detail : 'unknown error'));
            }
        }
        $database->commit();
    } catch (\Throwable $error) {
        $database->rollBack();
        throw $error;
    }
};
